"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["11447"],{45450(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>d,frontMatter:()=>r,contentTitle:()=>s,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"fundanalysis/usmarketrescue","title":"","description":"Author: [Mu Zi]","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/fundanalysis/usmarketrescue.md","sourceDirName":"fundanalysis","slug":"/fundanalysis/usmarketrescue","permalink":"/en/fundanalysis/usmarketrescue","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"usmarketrescue","title":"","hide_table_of_contents":true,"sidebar_label":"America\'s market bailout \u2014 a complete farce (2008-11-3 8:45:48)"},"sidebar":"fundAnalysisSidebar","previous":{"title":"The severity of economic adjustment must never be taken lightly (2008-9-18 8:22:18)","permalink":"/en/fundanalysis/severityofeconomicrecession"},"next":{"title":"Muzi: An economic person who can\'t make money is merely a \\"philanthropist\\"! (2008-11-17 10:24:50)","permalink":"/en/fundanalysis/economicman"}}'),o=n(74848),i=n(28453);let r={id:"usmarketrescue",title:"",hide_table_of_contents:!0,sidebar_label:"America's market bailout \u2014 a complete farce (2008-11-3 8:45:48)"},s="The U.S. Market Rescue: A Farce",l={},c=[];function h(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"the-us-market-rescue-a-farce",children:"The U.S. Market Rescue: A Farce"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsxs)(t.p,{children:["Author: [Mu Zi] ",(0,o.jsx)("br",{}),"\nSource: [Fund Analysis] ",(0,o.jsx)("br",{}),"\nArticle type: Recommended article ",(0,o.jsx)("br",{}),"\nPublished: 2008-11-3 8:45:48 ",(0,o.jsx)("br",{}),"\nColumn: Expert Perspectives"]}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"While China was on holiday for seven days, the U.S. House and Senate went back and forth, causing onlookers to jump with every twist, and finally passed a poison-pill rescue package. But global financial markets were not particularly grateful \u2014 most closed sharply lower that day. Setting aside the actual effectiveness of this rescue, the question that must now be asked is: is this $850 billion rescue fund manna from heaven?"}),"\n",(0,o.jsx)(t.p,{children:"What must be made clear about this global economic adjustment is that the ultimate task should be the thorough dismantling of the dollar system that has dominated the world economy for decades. The reason the American economy has reached this point is entirely self-inflicted. In previous economic crises, the existence of the dollar system allowed the U.S. to shift crises onto the rest of the world \u2014 maintaining an abnormally extravagant pattern of overconsumption and overuse. This pattern has already exceeded what the planet and the global economic system can bear. The arrangement where America consumes and the world picks up the tab \u2014 the time has come for it to be broken. America is now repeating its old tricks in an attempt to maintain the existing model. The original American model and the U.S.-dominated global economic order of recent decades \u2014 without thorough change \u2014 this global economic crisis will drag on endlessly with no resolution in sight."}),"\n",(0,o.jsx)(t.p,{children:"Now the $850 billion rescue plan has passed. But this $850 billion is absolutely not manna from heaven. It ultimately derives from the further inflation of the dollar bubble. The root cause of this global economic crisis is that the dollar has become thoroughly bubblified. The greatest risk and the greatest crisis is the dollar itself. This $850 billion not only further inflates the dollar bubble, threatening a full-blown crisis for the USD-denominated foreign exchange reserves of China and other nations, but will also cause liquidity in global financial markets to surge via the multiplier effect, pushing oil, grain, gold, and other commodity prices toward further frenzied rises. This will ultimately accelerate the bursting of the dollar bubble, which in turn will trigger the bursting of the commodity bubble \u2014 dragging the world economy into a dangerously regressive state."}),"\n",(0,o.jsx)(t.p,{children:"Facing this crisis, the correct Chinese posture should be: don't follow the herd. Absolutely do not tie ourselves to America's war chariot. Moreover, the current mode of market rescue is extremely wrongheaded. The government should not directly enter the market through fund vehicles. Instead, it should actively cultivate and lead new economic hotspots, creating more sectors for liquidity to participate in, thereby massively attracting capital that is seeking to decouple from the dollar system. As long as we ensure sufficiently long investment horizons for such capital and provide a favorable investment environment, allowing the capital to settle into the tide of China's far-more-promising high-speed development \u2014 then a large new reservoir, a new great world locomotive based on the RMB, can be established. America's crisis should become our catalyst for accelerated development."}),"\n",(0,o.jsx)(t.p,{children:'What demands particular attention now is that the government\'s entry into the stock market has already become a fait accompli. Therefore, the exit timing must be managed carefully to avoid repeating the debacle of the 1990s "777" rescue.'}),"\n",(0,o.jsx)(t.p,{children:"As long as we can act with our own interests as the priority \u2014 observing America's farce without participating, guarding only against the damage that America's farce-induced economic crisis might inflict on China's economy \u2014 then we have ample reason and confidence to preserve our strength through this global storm, adjust our economic development model and structure, and emerge after the storm in a new posture, rapidly entering a new cycle of economic growth."})]})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var a=n(96540);let o={},i=a.createContext(o);function r(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);